import {mountFinancials} from './financials.js';
import {repository,lessons,terms} from './data.js';
const $=s=>document.querySelector(s);const all=await repository.listCompanies();let saved;try{saved=JSON.parse(localStorage.getItem('jusik:saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{saved=[]}let current='home',query='',sector='전체',detail=false;const labels={home:'한눈에 보기',companies:'기업 둘러보기',learning:'배움의 공간',glossary:'투자 용어 사전',saved:'관심기업'};
const escapeHtml=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function spark(points,large=false){let ps=points.map((p,i)=>`${i*100/(points.length-1)},${100-p}`).join(' ');return `<svg class="${large?'detail-chart':'spark'}" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="예시 주가 추이" role="img"><polygon points="0,100 ${ps} 100,100" fill="#7f9f7210"/><polyline points="${ps}" fill="none" stroke="#83a178" stroke-width="${large?.8:1.4}" vector-effect="non-scaling-stroke"/></svg>`}
function cards(items){return items.length?items.map(c=>`<article class="company-card"><div class="company-head"><span class="logo ${c.tone}">${c.initial}</span><button class="star ${saved.includes(c.id)?'selected':''}" data-save="${c.id}" aria-label="${c.name} 관심기업 ${saved.includes(c.id)?'해제':'추가'}" aria-pressed="${saved.includes(c.id)}">${saved.includes(c.id)?'★':'☆'}</button></div><a class="company-title" href="#company-${c.id}">${c.name}</a><div class="company-meta">${c.market} · ${c.id} <span> / ${c.sector}</span></div><div class="price-row"><span class="price">${c.price}<small>원</small></span><span class="change ${c.change.startsWith('−')?'down':''}">${c.change}</span></div>${spark(c.points)}<div class="card-bottom"><span>예시 데이터</span><button data-company="${c.id}">기업 알아보기 ↗</button></div></article>`).join(''):'<div class="empty">표시할 기업이 없습니다.<br><br>기업 카드의 ☆를 눌러 관심기업을 추가해 보세요.</div>'}
function heading(title,sub){return `<section class="heading"><div><div class="eyebrow">YOUR INVESTING COMPANION</div><h1>${title}</h1><p class="subtext">${sub}</p></div><span class="date">◷ 화면 시연 · 예시 데이터</span></section>`}
const search=()=>`<label class="search"><span>⌕</span><input id="search" aria-label="기업명 또는 종목코드 검색" placeholder="궁금한 기업명, 종목코드를 검색해 보세요" value="${escapeHtml(query)}"></label>`;
function render(){document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===current);if(a.dataset.nav===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#crumb').textContent=labels[current];
if(current==='home')$('#main').innerHTML=heading('이해가 쌓이면, 투자가 달라집니다.','기업을 살펴보고, 개념을 배우며 나만의 투자 기준을 만들어 보세요.')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">작은 배움, 더 단단한 투자</div><h2>주가 너머의 기업을 읽는 힘,<br>여기서 시작하세요.</h2><p>어려운 재무 용어부터 눈여겨볼 위험 신호까지.<br>하나씩 이해하며 투자에 한 걸음 가까워지세요.</p><a href="#learning" class="primary">투자의 기초 배우기 <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><span class="art-arrow">↗</span><div class="bars"><span></span><span></span><span></span></div><span class="art-label">이해하는 만큼, 단단하게 ✦</span></div></section><div class="search-row"><div class="section-caption"><h2>어떤 기업이 궁금하세요?</h2><span>기업 탐색의 시작</span></div>${search()}</div><section class="cards" id="company-results">${cards(filtered())}</section><div class="lower-grid"><section class="panel"><div class="panel-top"><h2>하루 한 걸음, 투자 공부</h2><a class="text-link" href="#learning">전체 보기 ↗</a></div>${lessons.slice(0,3).map(l=>`<a class="learning-row" href="#lesson-${l.n}"><span class="lesson-icon">${l.icon}</span><div><small>STEP ${l.n} · ${l.category}</small><h3>${l.title}</h3><p>${l.text}</p></div><div class="lesson-end">${l.time}<b>${l.tag} ↗</b></div></a>`).join('')}</section><section class="panel term-panel"><div class="panel-top"><h2>오늘의 투자 용어</h2><span class="term-tag">알아두면 쓸모있는</span></div><h3>PER</h3><span class="term-ko">주가수익비율 · Price Earnings Ratio</span><p>이 기업의 이익에 비해 주가는 어느 정도일까요?<br>기업의 이익과 주가의 관계를 보여주는 숫자예요.</p><button class="term-button" data-term="0">쉬운 예시로 이해하기 <span>↗</span></button></section></div><div class="bottom-note"><span>♧</span><div><strong>숫자만큼 중요한 건, 그 숫자의 맥락이에요.</strong> &nbsp; 가격·차트는 예시입니다. 기업 상세의 OpenDART 재무정보는 별도 출처로 표시합니다.</div></div>`;
if(current==='companies'||current==='saved')$('#main').innerHTML=heading(labels[current],current==='saved'?'다시 살펴보고 싶은 기업을 한곳에 모아 보세요.':'기업의 사업과 숫자, 변화의 맥락을 함께 살펴보세요.')+`<div class="search-row"><div class="section-caption"><h2>${current==='saved'?'나의 관심기업':'기업 탐색'}</h2><span>예시 기업 4개</span></div>${search()}</div><div class="filters">${['전체','반도체','인터넷 서비스','자동차'].map(s=>`<button class="chip ${sector===s?'active':''}" data-filter="${s}">${s}</button>`).join('')}</div><section class="cards" id="company-results">${cards(filtered())}</section><div class="bottom-note">기업 상세에서 OpenDART 재무정보를 조회할 수 있습니다. 가격·차트는 예시이며 위험 평가는 제공하지 않습니다.</div>`;
if(current==='learning')$('#main').innerHTML=heading('배움이 나의 투자 기준이 되도록.','시장 기초부터 위험 관리까지, 차근차근 시작해 보세요.')+`<div class="full-lessons">${lessons.map(l=>`<article class="panel"><div class="eyebrow">STEP ${l.n} · ${l.category}</div><div class="lesson-icon">${l.icon}</div><h3>${l.title}</h3><p>${l.text}</p><a class="primary" href="#lesson-${l.n}">${l.time} 학습 미리보기 <span>↗</span></a></article>`).join('')}</div>`;
if(current==='glossary')$('#main').innerHTML=heading('어려운 용어를, 쉬운 언어로.','숫자 뒤에 숨은 의미를 하나씩 알아보세요.')+`<section class="glossary-list">${terms.map((t,i)=>`<button class="glossary-item" data-term="${i}"><b>${t.term}</b><span>${t.ko} ↗</span></button>`).join('')}</section>`;
}
function filtered(){return all.filter(c=>(current!=='saved'||saved.includes(c.id))&&(sector==='전체'||c.sector===sector)&&(c.name.toLowerCase().includes(query.toLowerCase())||c.id.includes(query)))}
function modal(html){$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2200)}
function term(i){const t=terms[i];modal(`<div class="eyebrow">한 번에 하나씩 · 투자 용어</div><h2>${t.term} <small style="font-size:14px;color:#8b9c81">${t.ko}</small></h2><p>${t.text}</p>${t.formula?`<div class="formula">${t.formula}</div>`:''}${i===0?`<p>주가가 10,000원, 주당순이익이 1,000원이면 PER은 <b id="per">10.0</b>배입니다.</p><label for="price-range">가상의 주가를 바꿔 보세요: <b id="range-value">10,000</b>원</label><input id="price-range" class="range" type="range" min="1000" max="30000" step="1000" value="10000"><p>업종, 성장성, 이익의 지속성도 함께 살펴야 합니다.</p>`:''}<div class="notice">설명 시연용 초안 · 정식 콘텐츠와 검수 출처는 추후 연결 예정</div>`)}
function company(id){const c=all.find(c=>c.id===id);if(!c)return;modal(`<div class="eyebrow">기업 알아보기 · 시세 예시 / 공시 재무 조회</div><h2>${c.name} <small style="font-size:12px;color:#94a389">${c.id}</small></h2><p>${c.market} · ${c.sector} <button class="chip" id="detail-toggle">${detail?'쉬운 설명':'상세 보기'}</button></p><div class="price">${c.price}원 <span class="change">${c.change}</span></div><div class="filters" style="margin:16px 0 0">${['1개월','3개월','1년'].map((s,i)=>`<button class="chip ${i===0?'active':''}" data-period="${i}" data-id="${id}">${s}</button>`).join('')}</div><div id="chart">${spark(c.points,true)}</div><section id="financials" aria-label="OpenDART 재무정보"></section><div class="detail-metrics"><div>사업 정보<b>${c.sector}</b></div><div>재무 데이터<b>OpenDART · 위 조회 결과 확인</b></div><div>위험 평가<b>평가 불가</b></div></div><h3 style="margin-top:24px;font-size:15px">위험 신호 살펴보기</h3>${['재무 건전성','시장 변동','공시 확인'].map(s=>`<div class="risk-row">${s}<span>분석 미제공 · 평가 불가</span></div>`).join('')}<p id="detail-explainer">${detail?'공시 재무정보의 출처·기준일·누락 상태는 위 조회 결과에서 확인하세요. 위험 분석은 제공하지 않습니다.':'재무정보 조회와 위험 평가는 별개입니다. 현재 위험 등급은 산출하지 않아요.'}</p><div class="notice">가격·변동률·차트는 임의의 예시입니다. 실제 시세가 아닙니다.<br>위 재무정보는 OpenDART 조회 결과이며 예시 시세와 별개입니다. 위험 등급은 산출하지 않습니다.</div>`);mountFinancials($('#financials'),id,repository)}
const lessonText={'01':'주식은 기업의 소유권을 나눈 단위입니다. 한 주를 보유하면 해당 기업의 주주가 됩니다. 기업의 성과에 따라 배당을 받을 수 있지만, 배당과 수익이 보장되지는 않습니다.','02':'매출은 기업이 상품과 서비스를 판매한 금액입니다. 영업이익은 본업에서 발생한 비용을 제외한 이익입니다. 이익과 현금흐름은 서로 다를 수 있습니다.','03':'PER은 주가와 주당순이익의 관계를 보여줍니다. 숫자가 낮다는 이유만으로 저평가를 확정할 수 없으며, 성장성과 이익의 지속성을 함께 살펴야 합니다.','04':'분산투자는 여러 자산에 나누어 투자하는 방법입니다. 특정 기업에 집중된 위험을 줄이는 데 도움이 되지만, 모든 손실 위험을 없애지는 못합니다.'};
function lesson(n){const l=lessons.find(l=>l.n===n);if(!l)return;const questions={'01':['주식을 사면 어떤 의미가 있나요?','기업의 일부를 소유하는 주주가 됩니다.','언제나 정해진 수익이 보장됩니다.'],'02':['영업이익과 현금흐름의 관계는?','서로 다를 수 있습니다.','언제나 같습니다.'],'03':['PER이 낮은 기업은?','성장성과 이익의 지속성을 함께 확인합니다.','항상 좋은 투자 대상입니다.'],'04':['분산투자를 하면?','집중 위험을 줄이는 데 도움이 됩니다.','모든 손실이 사라집니다.']};const q=questions[n];modal(`<div class="eyebrow">STEP ${n} · ${l.category} · 학습 미리보기</div><h2>${l.title}</h2><p>${lessonText[n]}</p><div class="formula">${q[0]}</div><button class="quiz-option" data-answer="true">${q[1]}</button><button class="quiz-option" data-answer="false">${q[2]}</button><div class="answer" role="status"></div><div class="notice">수업 화면 시연 · 학습 기록은 저장되지 않습니다.</div>`)}
function route(){const h=location.hash.slice(1)||'home';if(h.startsWith('company-')){company(h.slice(8));return}if(h.startsWith('lesson-')){lesson(h.slice(7));return}if(labels[h]){if($('#dialog').open)$('#dialog').close();current=h;query='';sector='전체';render();window.scrollTo(0,0)}}window.addEventListener('hashchange',route);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.save){const id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('jusik:saved',JSON.stringify(saved))}catch{}$('#company-results').innerHTML=cards(filtered());toast(saved.includes(id)?'관심기업에 추가했습니다 · 이 브라우저에 저장':'관심기업에서 해제했습니다')}if(b.dataset.company)company(b.dataset.company);if(b.dataset.term)term(Number(b.dataset.term));if(b.dataset.filter){sector=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===sector));$('#company-results').innerHTML=cards(filtered())}if(b.dataset.period){document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('active',x===b));const c=all.find(c=>c.id===b.dataset.id);let p=[...c.points];if(b.dataset.period==='1')p=p.slice().reverse();if(b.dataset.period==='2')p=p.map((x,i)=>Math.min(95,20+i*5+x/4));$('#chart').innerHTML=spark(p,true)}if(b.id==='detail-toggle'){detail=!detail;b.textContent=detail?'쉬운 설명':'상세 보기';$('#detail-explainer').textContent=detail?'공시 재무정보의 출처·기준일·누락 상태는 위 조회 결과에서 확인하세요. 위험 분석은 제공하지 않습니다.':'재무정보 조회와 위험 평가는 별개입니다. 현재 위험 등급은 산출하지 않아요.'}if(b.dataset.answer){b.classList.add(b.dataset.answer==='true'?'correct':'wrong');$('.answer').textContent=b.dataset.answer==='true'?'맞아요! 개념을 한 단계 이해했어요.':'다시 살펴보세요. 위의 설명에서 답을 찾아볼 수 있어요.'}if(b.classList.contains('close'))$('#dialog').close();if(b.id==='help'||b.id==='sources')modal('<div class="eyebrow">ABOUT THIS PREVIEW</div><h2>이해에서 시작하는 투자</h2><p>기업 탐색과 투자 교육을 연결하는 웹앱의 UI 시제품입니다. 기업명은 실제 기업이며, 가격·변동률·차트는 임의의 예시입니다.</p><p>기업 상세의 재무정보는 서버를 통해 금융감독원 OpenDART에서 조회하며, 출처·재무 기준일·공시일·조회 시각·연결/별도 기준을 따로 표시합니다. 기본 조회는 전년도 사업보고서이며 최신 공시 자동선택이 아닙니다. 키 미설정·오류·결측은 자료 없음, 위험 평가는 평가 불가입니다. 가격·변동률·차트·PER 실습은 예시입니다.</p><div class="notice">관심기업은 현재 브라우저에만 저장됩니다. 용어 및 학습 설명은 정식 검수 전 초안입니다.</div>')});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#company-results').innerHTML=cards(filtered())}if(e.target.id==='price-range'){$('#range-value').textContent=Number(e.target.value).toLocaleString('ko-KR');$('#per').textContent=(e.target.value/1000).toFixed(1)}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close()}});$('#dialog').addEventListener('close',()=>{if(location.hash.startsWith('#company-')||location.hash.startsWith('#lesson-'))history.replaceState(null,'',`#${current}`)});render();route();
